    a[ks][0] = *reinterpret_cast<const uint32_t*>(r);
    a[ks][1] = *reinterpret_cast<const uint32_t*>(r + 8 * kDim);
    a[ks][2] = *reinterpret_cast<const uint32_t*>(r + 8);
    a[ks][3] = *reinterpret_cast<const uint32_t*>(r + 8 * kDim + 8);
  }
