          \"+f\"(s[3][0]),\"+f\"(s[3][1]),\"+f\"(s[3][2]),\"+f\"(s[3][3]),
          \"+f\"(s[4][0]),\"+f\"(s[4][1]),\"+f\"(s[4][2]),\"+f\"(s[4][3]),
          \"+f\"(s[5][0]),\"+f\"(s[5][1]),\"+f\"(s[5][2]),\"+f\"(s[5][3]),
