        \"+f\"(D[42]), \"+f\"(D[43]), \"+f\"(D[44]), \"+f\"(D[45]), \"+f\"(D[46]),          \\
        \"+f\"(D[47]), \"+f\"(D[48]), \"+f\"(D[49]), \"+f\"(D[50]), \"+f\"(D[51]),          \\
        \"+f\"(D[52]), \"+f\"(D[53]), \"+f\"(D[54]), \"+f\"(D[55]), \"+f\"(D[56]),          \\
        \"+f\"(D[57]), \"+f\"(D[58]), \"+f\"(D[59]), \"+f\"(D[60]), \"+f\"(D[61]),          \\
        \"+f\"(D[62]), \"+f\"(D[63])                                                  \\
      : \"r\"(EN), \"r\"(A[0]), \"r\"(A[1]), \"r\"(A[2]), \"r\"(A[3]), \"l\"(DESC))

__global__ void __launch_bounds__(kThreads, 1)
block_sparse_kernel(const bf16* __restrict__ q, const bf16* __restrict__ k,
                    const bf16* __restrict__ v, const int* __restrict__ block_ids,
                    const int* __restrict__ block_counts, bf16* __restrict__ out, int seq,
                    int nblocks) {
  extern __shared__ unsigned char smem_raw[];
  Shared& sm = *reinterpret_cast<Shared*>(smem_raw);

  const int tid = threadIdx.x;
  const int lane = tid & 31;
  const int warp = tid >> 5;
  const int wg = warp >> 2;         // warpgroup 0/1
  const int wgw = warp & 3;         // warp inside the warpgroup
  const int gid = lane >> 2, tig = lane & 3;
  const int row_lo = wg * kKeys + wgw * 16 + gid;

  const int qb = blockIdx.x;
  const int hq = blockIdx.y;
  const int b = blockIdx.z;
  const int hkv = hq / (kHeads / kKVHeads);

  // Q A-fragments: 8 k-steps x 4 registers, loaded straight from the contiguous plane.
  uint32_t aq[8][4];
  {
    const bf16* qrow = q + (((size_t)b * kHeads + hq) * seq + (size_t)qb * kRows + row_lo) * kDim +
                       2 * tig;
    #pragma unroll
    for (int ks = 0; ks < 8; ++ks) {
      aq[ks][0] = *reinterpret_cast<const uint32_t*>(qrow + ks * 16);
      aq[ks][1] = *reinterpret_cast<const uint32_t*>(qrow + 8 * kDim + ks * 16);
      aq[ks][2] = *reinterpret_cast<const uint32_t*>(qrow + ks * 16 + 8);
      aq[ks][3] = *reinterpret_cast<const uint32_t*>(qrow + 8 * kDim + ks * 16 + 8);
    }
  }

  if (tid == 0) {
    const size_t head = ((size_t)b * kHeads + hq) * nblocks + qb;
    const int count = block_counts[head];
    const int* ids = block_ids + head * kCapacity;
    int n = 0;
    for (int j = 0; j < count; ++j) {
      const int bid = ids[j];
      if (bid < 0 || bid > qb) continue;
      #pragma unroll
      for (int t = 0; t < kTilesPerBlock; ++t) {
        sm.tile_src[n] = (bid * kRows + t * kKeys) * kDim;
        sm.tile_key[n] = t * kKeys;
        sm.tile_diag[n] = (bid == qb) ? 1 : 0;
        ++n;
      }
    }
    sm.ntiles = n;
  }

  const bf16* kbase = k + (((size_t)b * kKVHeads + hkv) * seq) * kDim;
  const bf16* vbase = v + (((size_t)b * kKVHeads + hkv) * seq) * kDim;

  // Each 16 B chunk is one 8-dim block of one key row; the interleaved layout
  // keeps those 8 halves contiguous, so cp.async can write them directly.
  auto prefetch = [&](int ti, int stage) {
    const bf16* kp = kbase + sm.tile_src[ti];
    const bf16* vp = vbase + sm.tile_src[ti];
    #pragma unroll
    for (int i = 0; i < kTileElems * 2 / 16 / kThreads; i += 2) {
      const int e = tid + i * kThreads;
      const int key = e >> 4, db = e & 15;
      const int dst = ((key >> 3) * 16 + db) * 64 + (key & 7) * 8;
      cp_async16(&sm.ks[stage][dst], kp + key * kDim + db * 8);
      cp_async16(&sm.vs[stage][dst], vp + key * kDim + db * 8);
    }
    cp_commit();
  };

  float acc[64];
  #pragma unroll
  for (int i = 0; i < 64; ++i) acc[i] = 0.f;
  float rmax[2] = {-INFINITY, -INFINITY};
  float rsum[2] = {0.f, 0.f};

  __syncthreads();
  const int ntiles = sm.ntiles;
  if (ntiles > 0) prefetch(0, 0);
  if (ntiles > 1) prefetch(1, 1 % kStages);

  for (int ti = 0; ti < ntiles; ++ti) {
    if (ti + 1 < ntiles) cp_wait<1>(); else cp_wait<0>();
    __syncthreads();
    if (ti + kStages - 1 < ntiles) prefetch(ti + kStages - 1, (ti + kStages - 1) % kStages);

    const int diag = sm.tile_diag[ti];
    if (diag && sm.tile_key[ti] > row_lo + 7) continue;   // whole warpgroup masked

    const int stage = ti % kStages;
    const bf16* ktile = sm.ks[stage];
    const bf16* vtile = sm.vs[stage];

    // S = Q K"'^T (m64n64k16 x8).
    float s[32];
    #pragma unroll
    for (int i = 0; i < 32; ++i) s[i] = 0.f;
    wfence();
    #pragma unroll
    for (int ks = 0; ks < 8; ++ks) {
      const uint64_t dk = gdesc(ktile + ks * 128, 128, 2048);
      WGMMA_M64N64(s, aq[ks], dk, 1);
    }
    wcommit();
    wwait<0>();

    // Base-2 scores and causal masking on the diagonal tile.
    #pragma unroll
    for (int i = 0; i < 32; ++i) s[i] *= kScaleLog2e;
    if (diag) {
      #pragma unroll
      for (int cg = 0; cg < 8; ++cg) {
        #pragma unroll
        for (int rr = 0; rr < 2; ++rr) {
          const int row = row_lo + 8 * rr;
          const int c0 = sm.tile_key[ti] + 8 * cg + 2 * tig;
          s[4 * cg + 2 * rr + 0] = (c0 <= row) ? s[4 * cg + 2 * rr + 0] : -INFINITY;
          s[4 * cg + 2 * rr + 1] = (c0 + 1 <= row) ? s[4 * cg + 2 * rr + 1] : -INFINITY;
        }
      }
    }

    // Row max over the 64 keys: 16 columns per thread, four lanes per row.
    float mx0 = -INFINITY, mx1 = -INFINITY;
    #pragma unroll
    for (int cg = 0; cg < 8; ++cg) {
      mx0 = fmaxf(mx0, fmaxf(s[4 * cg + 0], s[4 * cg + 1]));
      mx1 = fmaxf(mx1, fmaxf(s[4 * cg + 2], s[4 * cg + 3]));
    }
    mx0 = fmaxf(mx0, __shfl_xor_sync(0xffffffffu, mx0, 1));
    mx0 = fmaxf(mx0, __shfl_xor_sync(0xffffffffu, mx0, 2));
    mx1 = fmaxf(mx1, __shfl_xor_sync(0xffffffffu, mx1, 1));
    mx1 = fmaxf(mx1, __shfl_xor_sync(0xffffffffu, mx1, 2));

    const float m0 = fmaxf(rmax[0], mx0);
    const float m1 = fmaxf(rmax[1], mx1);
    const float a0 = ex2(rmax[0] - m0);
    const float a1 = ex2(rmax[1] - m1);
    rmax[0] = m0; rmax[1] = m1;
    #pragma unroll
    for (int cg = 0; cg < 8; ++cg) {
      acc[4 * cg + 0] *= a0; acc[4 * cg + 1] *= a0;
      acc[4 * cg + 2] *= a1; acc[4 * cg + 3] *= a1;
    }

    float sum0 = 0.f, sum1 = 0.f;
    #pragma unroll
    for (int cg = 0; cg < 8; ++cg) {
      s[4 * cg + 0] = ex2(s[4 * cg + 0] - m0);
      s[4 * cg + 1] = ex2(s[4 * cg + 1] - m0);
      s[4 * cg + 2] = ex2(s[4 * cg + 2] - m1);
      s[4 * cg + 3] = ex2(s[4 * cg + 3] - m1);
      sum0 += s[4 * cg + 0] + s[4 * cg + 1];
      sum1 += s[4 * cg + 2] + s[4 * cg + 3];
    }
    sum0 += __shfl_xor_sync(0xffffffffu, sum0, 1);
    sum0 += __shfl_xor_sync(0xffffffffu, sum0, 2);
    sum1 += __shfl_xor_sync(0xffffffffu, sum1, 1);
    sum1 += __shfl_xor_sync(0xffffffffu, sum1, 2);
    rsum[0] = rsum[0] * a0 + sum0;
    rsum[1] = rsum[1] * a1 + sum1;

    // P (bf16) in the A-fragment layout: register pairs pack directly.
    uint32_t p[4][4];
    #pragma unroll
    for (int ks = 0; ks < 4; ++ks) {
      p[ks][0] = pack_bf16(s[8 * ks + 0], s[8 * ks + 1]);
      p[ks][1] = pack_bf16(s[8 * ks + 2], s[8 * ks + 3]);
      p[ks][2] = pack_bf16(s[8 * ks + 4], s[8 * ks + 5]);
      p[ks][3] = pack_bf16(s[8 * ks + 6], s[8 * ks + 7]);
    }

    // O += P V (m64n128k16 x4).
    wfence();
    #pragma unroll
    for (int ks = 0; ks < 4; ++ks) {
      const uint64_t dv = gdesc(vtile + ks * 2048, 2048, 128);
      WGMMA_M64N128(acc, p[ks], dv, 1);
    }
    wcommit();
    wwait<0>();
  }

  const float i0 = rsum[0] > 0.f ? 1.f / rsum[0] : 0.f;
  const float i1 = rsum[1] > 0.f ? 1.f / rsum[1] : 0.f;
  bf16* orow = out + (((size_t)b * kHeads + hq) * seq + (size_t)qb * kRows + row_lo) * kDim + 2 * tig;
  #pragma unroll
  for (int cg = 0; cg < 16; ++cg) {
    *reinterpret_cast<uint32_t*>(orow + cg * 8) =
        pack_bf16(acc[4 * cg + 0] * i0, acc[4 * cg + 1] * i0);
    *reinterpret_cast<uint32_t*>(orow + 8 * kDim + cg * 8) =
        pack_bf16(acc[4 * cg + 2] * i1, acc[4 * cg + 3] * i1);
  }
}
