   112	  const int tid = threadIdx.x;
   113	  const int lane = tid & 31;
   114	  const int warp = tid >> 5;
   115	  const int groupID = lane >> 2;
   116	  const int tig = lane & 3;
   117	  const int row_group = warp * kRowTile;
   118	
   119	  const int qb = blockIdx.x;
   120	  const int hq = blockIdx.y;
   121	  const int b = blockIdx.z;
   122	  const int hkv = hq / (kHeads / kKVHeads);
   123	
   124	  // Q mma A-fragments: (row, k) pairs live in one b32 per lane, loaded straight
   125	  // from the contiguous plane (row stride 128 halves, pair alignment 4 B).
   126	  uint32_t aq[8][4];
   127	  {
   128	    const bf16* qrow = q + (((size_t)b * kHeads + hq) * seq + (size_t)qb * kRows + row_group +
   129	                            groupID) * kDim + 2 * tig;
   130	    #pragma unroll
   131	    for (int kt = 0; kt < 8; ++kt) {
   132	      aq[kt][0] = *reinterpret_cast<const uint32_t*>(qrow + kt * 16);
   133	      aq[kt][1] = *reinterpret_cast<const uint32_t*>(qrow + 8 * kDim + kt * 16);
   134	      aq[kt][2] = *reinterpret_cast<const uint32_t*>(qrow + kt * 16 + 8);
   135	      aq[kt][3] = *reinterpret_cast<const uint32_t*>(qrow + 8 * kDim + kt * 16 + 8);
   136	    }
   137	  }
   138	
   139	  // Flatten the selected blocks into 64-key tiles; skip blocks whose keys are
   140	  // entirely after the diagonal.
   141	  if (tid == 0) {
   142	    const size_t head = ((size_t)b * kHeads + hq) * nblocks + qb;
   143	    const int count = block_counts[head];
   144	    const int* ids = block_ids + head * kCapacity;
   145	    int n = 0;
   146	    for (int j = 0; j < count; ++j) {
   147	      const int bid = ids[j];
   148	      if (bid < 0 || bid > qb) continue;
   149	      #pragma unroll
   150	      for (int t = 0; t < kTilesPerBlock; ++t) {
   151	        sm.tile_src[n] = (bid * kRows + t * kKeys) * kDim;
   152	        sm.tile_key[n] = t * kKeys;
   153	        sm.tile_diag[n] = (bid == qb) ? 1 : 0;
   154	        ++n;
   155	      }
   156	    }
   157	    sm.ntiles = n;
   158	  }
   159	
   160	  const bf16* kbase = k + (((size_t)b * kKVHeads + hkv) * seq) * kDim;
   161	  const bf16* vbase = v + (((size_t)b * kKVHeads + hkv) * seq) * kDim;
   162	
   163	  auto prefetch = [&](int ti, int stage) {
   164	    const bf16* kp = kbase + sm.tile_src[ti];
   165	    const bf16* vp = vbase + sm.tile_src[ti];
   166	    #pragma unroll
   167	    for (int i = 0; i < kKeys * 16 / kThreads; ++i) {
   168	      const int e = tid + i * kThreads;
   169	      const int r = e >> 4;
   170	      const int c = (e & 15) * 8;
   171	      cp_async16(&sm.ks[stage][r][c], kp + (size_t)r * kDim + c);
   172	      cp_async16(&sm.vs[stage][r][c], vp + (size_t)r * kDim + c);
   173	    }
   174	    cp_commit();
   175	  };
   176	
   177	  float acc[16][4];
   178	  #pragma unroll
   179	  for (int nt = 0; nt < 16; ++nt) {
   180	    acc[nt][0] = 0.f; acc[nt][1] = 0.f; acc[nt][2] = 0.f; acc[nt][3] = 0.f;
   181	  }
   182	  float rowmax[2] = {-INFINITY, -INFINITY};
   183	  float rowsum[2] = {0.f, 0.f};
   184	
   185	  __syncthreads();
   186	  const int ntiles = sm.ntiles;
   187	  if (ntiles > 0) prefetch(0, 0);
   188	  if (ntiles > 1) prefetch(1, 1);
   189	
   190	  for (int ti = 0; ti < ntiles; ++ti) {
   191	    if (ti + 1 < ntiles) cp_wait<1>();
   192	    else cp_wait<0>();
   193	    __syncthreads();
   194	    if (ti + kStages - 1 < ntiles) prefetch(ti + kStages - 1, (ti + kStages - 1) % kStages);
   195	
   196	    const int diag = sm.tile_diag[ti];
   197	    // A tile fully beyond this warp's diagonal holds no allowed score.
   198	    if (diag && sm.tile_key[ti] > row_group + kRowTile - 1) continue;
   199	
   200	    const int stage = ti % kStages;
   201	    const int lrow = lane & 15;         // key row inside the 16-key group
   202	    const int lcol = (lane & 16) >> 1;  // 0 or 8: dimension half of the 16-wide group
   203	
   204	    // S = Q K^T over the 64-key tile: 8 key-tiles of 8 keys x 8 k-steps.
   205	    float s[8][4];
   206	    #pragma unroll
   207	    for (int nt = 0; nt < 8; ++nt) {
   208	      s[nt][0] = 0.f; s[nt][1] = 0.f; s[nt][2] = 0.f; s[nt][3] = 0.f;
   209	    }
   210	    #pragma unroll
   211	    for (int kt = 0; kt < 8; ++kt) {
   212	      #pragma unroll
   213	      for (int g = 0; g < 4; ++g) {
   214	        uint32_t r0, r1, r2, r3;
   215	        ldsm_x4(smem_u32(&sm.ks[stage][g * 16 + lrow][kt * 16 + lcol]), r0, r1, r2, r3);
   216	        mma_bf16(s[2 * g], aq[kt], r0, r2);
   217	        mma_bf16(s[2 * g + 1], aq[kt], r1, r3);
   218	      }
   219	    }
   220	
   221	    // Base-2 scores; the causal tile masks everything past the row position.
   222	    #pragma unroll
   223	    for (int nt = 0; nt < 8; ++nt) {
   224	      s[nt][0] *= kScaleLog2e;
   225	      s[nt][1] *= kScaleLog2e;
   226	      s[nt][2] *= kScaleLog2e;
   227	      s[nt][3] *= kScaleLog2e;
   228	    }
   229	    if (diag) {
   230	      const int row_lo = row_group + groupID;
   231	      #pragma unroll
   232	      for (int nt = 0; nt < 8; ++nt) {
   233	        const int c = sm.tile_key[ti] + nt * 8 + 2 * tig;
   234	        s[nt][0] = (c <= row_lo) ? s[nt][0] : -INFINITY;
   235	        s[nt][1] = (c + 1 <= row_lo) ? s[nt][1] : -INFINITY;
   236	        s[nt][2] = (c <= row_lo + 8) ? s[nt][2] : -INFINITY;
   237	        s[nt][3] = (c + 1 <= row_lo + 8) ? s[nt][3] : -INFINITY;
   238	      }
   239	    }
   240	
   241	    // Online softmax: one row maximum and sum per warp row (4-lane reduce).
   242	    float mx0 = -INFINITY, mx1 = -INFINITY;
   243	    #pragma unroll
   244	    for (int nt = 0; nt < 8; ++nt) {
   245	      mx0 = fmaxf(mx0, fmaxf(s[nt][0], s[nt][1]));
   246	      mx1 = fmaxf(mx1, fmaxf(s[nt][2], s[nt][3]));
   247	    }
   248	    mx0 = fmaxf(mx0, __shfl_xor_sync(0xffffffffu, mx0, 1));
   249	    mx0 = fmaxf(mx0, __shfl_xor_sync(0xffffffffu, mx0, 2));
   250	    mx1 = fmaxf(mx1, __shfl_xor_sync(0xffffffffu, mx1, 1));
   251	    mx1 = fmaxf(mx1, __shfl_xor_sync(0xffffffffu, mx1, 2));
   252	
   253	    const float m0 = fmaxf(rowmax[0], mx0);
   254	    const float m1 = fmaxf(rowmax[1], mx1);
   255	    const float alpha0 = ex2(rowmax[0] - m0);
   256	    const float alpha1 = ex2(rowmax[1] - m1);
   257	    rowmax[0] = m0;
   258	    rowmax[1] = m1;
   259	
   260	    #pragma unroll
   261	    for (int nt = 0; nt < 16; ++nt) {
   262	      acc[nt][0] *= alpha0;
   263	      acc[nt][1] *= alpha0;
   264	      acc[nt][2] *= alpha1;
   265	      acc[nt][3] *= alpha1;
   266	    }
   267	
   268	    float sum0 = 0.f, sum1 = 0.f;
   269	    #pragma unroll
   270	    for (int nt = 0; nt < 8; ++nt) {
   271	      s[nt][0] = ex2(s[nt][0] - m0);
   272	      s[nt][1] = ex2(s[nt][1] - m0);
   273	      s[nt][2] = ex2(s[nt][2] - m1);
   274	      s[nt][3] = ex2(s[nt][3] - m1);
   275	      sum0 += s[nt][0] + s[nt][1];
   276	      sum1 += s[nt][2] + s[nt][3];
   277	    }
   278	    sum0 += __shfl_xor_sync(0xffffffffu, sum0, 1);
   279	    sum0 += __shfl_xor_sync(0xffffffffu, sum0, 2);
   280	    sum1 += __shfl_xor_sync(0xffffffffu, sum1, 1);
   281	    sum1 += __shfl_xor_sync(0xffffffffu, sum1, 2);
   282	    rowsum[0] = rowsum[0] * alpha0 + sum0;
   283	    rowsum[1] = rowsum[1] * alpha1 + sum1;
   284	
   285	    // O += P V: rounded BF16 probabilities, V read transposed from shared.
   286	    #pragma unroll
   287	    for (int kk = 0; kk < 4; ++kk) {
   288	      const uint32_t afrag[4] = {pack_bf16(s[2 * kk][0], s[2 * kk][1]),
   289	                                 pack_bf16(s[2 * kk][2], s[2 * kk][3]),
   290	                                 pack_bf16(s[2 * kk + 1][0], s[2 * kk + 1][1]),
   291	                                 pack_bf16(s[2 * kk + 1][2], s[2 * kk + 1][3])};
   292	      #pragma unroll
   293	      for (int dd = 0; dd < 8; ++dd) {
   294	        uint32_t r0, r1, r2, r3;
   295	        ldsm_x4_t(smem_u32(&sm.vs[stage][kk * 16 + lrow][dd * 16 + lcol]), r0, r1, r2, r3);
   296	        mma_bf16(acc[2 * dd], afrag, r0, r1);
   297	        mma_bf16(acc[2 * dd + 1], afrag, r2, r3);
   298	      }
   299	    }
   300	  }
   301	
   302	  // Normalize and store: rows groupID and groupID+8 of this warp.
   303	  const float inv0 = rowsum[0] > 0.f ? 1.f / rowsum[0] : 0.f;
   304	  const float inv1 = rowsum[1] > 0.f ? 1.f / rowsum[1] : 0.f;
   305	  bf16* orow = out + (((size_t)b * kHeads + hq) * seq + (size_t)qb * kRows + row_group +
   306	                      groupID) * kDim + 2 * tig;
   307	  #pragma unroll
   308	  for (int nt = 0; nt < 16; ++nt) {
   309	    *reinterpret_cast<uint32_t*>(orow + nt * 8) =
   310	        pack_bf16(acc[nt][0] * inv0, acc[nt][1] * inv0);
   311	    *reinterpret_cast<uint32_t*>(orow + 8 * kDim + nt * 8) =
   312	        pack_bf16(acc[nt][2] * inv1, acc[nt][3] * inv1);
   313	  }
   314	}
   315	
   316	void check_input(const torch::Tensor& t, torch::ScalarType dtype) {
   317	  TORCH_CHECK_VALUE(t.is_cuda(), "expected CUDA tensor");
   318	  TORCH_CHECK_TYPE(t.scalar_type() == dtype, "unexpected dtype");
   319	  TORCH_CHECK_VALUE(t.is_contiguous(), "expected contiguous tensor");
   320	}
   321	
   322	void kernel(const torch::Tensor& q, const torch::Tensor& k, const torch::Tensor& v,
   323	            const torch::Tensor& block_ids, const torch::Tensor& block_counts,
   324	            const torch::Tensor& out) {
   325	  check_input(q, torch::kBFloat16);
   326	  check_input(k, torch::kBFloat16);
   327	  check_input(v, torch::kBFloat16);
   328	  check_input(out, torch::kBFloat16);
   329	  check_input(block_ids, torch::kInt32);
   330	  check_input(block_counts, torch::kInt32);
   331	
   332	  TORCH_CHECK_VALUE(q.dim() == 4 && k.dim() == 4 && v.dim() == 4, "expected rank 4 q/k/v");
   333	  TORCH_CHECK_VALUE(block_ids.dim() == 4 && block_counts.dim() == 3, "expected rank 4/3 masks");
   334	  const int64_t batch = q.size(0);
   335	  const int64_t heads = q.size(1);
   336	  const int64_t seq = q.size(2);
   337	  const int64_t dim = q.size(3);
   338	  const int64_t nblocks = block_ids.size(2);
   339	  TORCH_CHECK_VALUE(heads == kHeads && dim == kDim, "heads/dim mismatch");
   340	  TORCH_CHECK_VALUE(k.size(1) == kKVHeads && v.size(1) == kKVHeads, "kv head mismatch");
   341	  TORCH_CHECK_VALUE(k.size(2) == seq && v.size(2) == seq, "kv sequence mismatch");
   342	  TORCH_CHECK_VALUE(block_ids.size(1) == heads && block_ids.size(3) == kCapacity,
   343	                    "mask shape mismatch");
   344	  TORCH_CHECK_VALUE(block_counts.size(0) == batch && block_counts.size(1) == heads &&
   345	                    block_counts.size(2) == nblocks, "count shape mismatch");
   346	  TORCH_CHECK_VALUE(nblocks > 0 && seq == nblocks * kRows,
   347	                    "block size must be 128");
   348	  TORCH_CHECK_VALUE(out.sizes() == q.sizes(), "output shape mismatch");
   349	  TORCH_CHECK_VALUE(q.device() == out.device() && q.device() == k.device(), "device mismatch");
   350	  if (batch == 0) return;
   351	
   352	  c10::cuda::CUDAGuard guard(q.device());
   353	  const cudaStream_t stream = c10::cuda::getCurrentCUDAStream(q.get_device()).stream();
   354	  const int smem_bytes = sizeof(Shared);
   355	  static bool smem_configured = false;
   356	  if (!smem_configured) {
   357	    cudaFuncSetAttribute(block_sparse_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize,
   358	                         smem_bytes);
   359	    smem_configured = true;
   360	  }
   361	
   362	  const dim3 grid((unsigned)nblocks, (unsigned)heads, (unsigned)batch);
   363	  block_sparse_kernel<<<grid, kThreads, smem_bytes, stream>>>(
   364	      reinterpret_cast<const bf16*>(q.data_ptr()), reinterpret_cast<const bf16*>(k.data_ptr()),
   365	      reinterpret_cast<const bf16*>(v.data_ptr()), block_ids.data_ptr<int>(),
   366	      block_counts.data_ptr<int>(), reinterpret_cast<bf16*>(out.data_ptr()), (int)seq,
   367	      (int)nblocks);
   368	  const cudaError_t error = cudaGetLastError();
   369	  TORCH_CHECK(error == cudaSuccess, cudaGetErrorString(error));
   370	}
