   372	
   373	PYBIND11_MODULE(TORCH_EXTENSION_NAME, module) {
   374	  module.def("kernel", &kernel);
   375	}

  return *reinterpret_cast<const uint32_t*>(&pair);
}

__device__ __forceinline__ float ex2(float x) {
  float y;
  asm("ex2.approx.f32 %0, %1;" : "=f"(y) : "f"(x));
  return y;
}

__global__ void __launch_bounds__(kThreads, 1)
block_sparse_kernel(const bf16* __restrict__ q, const bf16* __restrict__ k,
                    const bf16* __restrict__ v, const int* __restrict__ block_ids,
                    const int* __restrict__ block_counts, bf16* __restrict__ out, int seq,
                    int nblocks) {
  extern __shared__ unsigned char smem_raw[];
  Shared& sm = *reinterpret_cast<Shared*>(smem_raw);

  const int tid = threadIdx.x;
  const int lane = tid & 31;
  const int warp = tid >> 5;
  const int groupID = lane >> 2;
  const int tig = lane & 3;
  const int row_group = warp * kRowTile;

  const int qb = blockIdx.x;
  const int hq = blockIdx.y;
  const int b = blockIdx.z;
  const int hkv = hq / (kHeads / kKVHeads);

  // Q mma A-fragments: (row, k) pairs live in one b32 per lane, loaded straight
  // from the contiguous plane (row stride 128 halves, pair alignment 4 B).
  uint32_t aq[8][4];
  {
    const bf16* qrow = q + (((size_t)b * kHeads + hq) * seq + (size_t)qb * kRows + row_group +
                            groupID) * kDim + 2 * tig;
    #pragma unroll
    for (int kt = 0; kt < 8; ++kt) {
      aq[kt][0] = *reinterpret_cast<const uint32_t*>(qrow + kt * 16);
      aq[kt][1] = *reinterpret_cast<const uint32_t*>(qrow + 8 * kDim + kt * 16);
      aq[kt][2] = *reinterpret_cast<const uint32_t*>(qrow + kt * 16 + 8);
      aq[kt][3] = *reinterpret_cast<const uint32_t*>(qrow + 8 * kDim + kt * 16 + 8);
    }
  }

  // Flatten the selected blocks into 64-key tiles; skip blocks whose keys are
  // entirely after the diagonal.
  if (tid == 0) {
    const size_t head = ((size_t)b * kHeads + hq) * nblocks + qb;
    const int count = block_counts[head];
    const int* ids = block_ids + head * kCapacity;
    int n = 0;
    for (int j = 0; j < count; ++j) {
      const int bid = ids[j];
      if (bid < 0 || bid > qb) continue;
      #pragma unroll
      for (int t = 0; t < kTilesPerBlock; ++t) {
        sm.tile_src[n] = (bid * kRows + t * kKeys) * kDim;
        sm.tile_key[n] = t * kKeys;
        sm.tile_diag[n] = (bid == qb) ? 1 : 0;
        ++n;
      }
    }
    sm.ntiles = n;
  }

  const bf16* kbase = k + (((size_t)b * kKVHeads + hkv) * seq) * kDim;
  const bf16* vbase = v + (((size_t)b * kKVHeads + hkv) * seq) * kDim;

  auto prefetch = [&](int ti, int stage) {
    const bf16* kp = kbase + sm.tile_src[ti];
    const bf16* vp = vbase + sm.tile_src[ti];
    #pragma unroll
    for (int i = 0; i < kKeys * 16 / kThreads; ++i) {
      const int e = tid + i * kThreads;
      const int r = e >> 4;
      const int c = (e & 15) * 8;
      cp_async16(&sm.ks[stage][r][c], kp + (size_t)r * kDim + c);
      cp_async16(&sm.vs[stage][r][c], vp + (size_t)r * kDim + c);
    }
    cp_commit();
  };

  float acc[16][4];
  #pragma unroll
  for (int nt = 0; nt < 16; ++nt) {
    acc[nt][0] = 0.f; acc[nt][1] = 0.f; acc[nt][2] = 0.f; acc[nt][3] = 0.f;
  }
  float rowmax[2] = {-INFINITY, -INFINITY};
  float rowsum[2] = {0.f, 0.f};

  __syncthreads();
  const int ntiles = sm.ntiles;
  if (ntiles > 0) prefetch(0, 0);
  if (ntiles > 1) prefetch(1, 1);

  for (int ti = 0; ti < ntiles; ++ti) {
    if (ti + 1 < ntiles) cp_wait<1>();
    else cp_wait<0>();
    __syncthreads();
    if (ti + kStages - 1 < ntiles) prefetch(ti + kStages - 1, (ti + kStages - 1) % kStages);

    const int diag = sm.tile_diag[ti];
    // A tile fully beyond this warp's diagonal holds no allowed score.
    if (diag && sm.tile_key[ti] > row_group + kRowTile - 1) continue;

    const int stage = ti % kStages;
    const int lrow = lane & 15;         // key row inside the 16-key group
    const int lcol = (lane & 16) >> 1;  // 0 or 8: dimension half of the 16-wide group

    // S = Q K^T over the 64-key tile: 8 key-tiles of 8 keys x 8 k-steps.
    float s[8][4];
    #pragma unroll
    for (int nt = 0; nt < 8; ++nt) {
      s[nt][0] = 0.f; s[nt][1] = 0.f; s[nt][2] = 0.f; s[nt][3] = 0.f;
    }
    #pragma unroll
    for (int kt = 0; kt < 8; ++kt) {
      #pragma unroll
      for (int g = 0; g < 4; ++g) {
        uint32_t r0, r1, r2, r3;
        ldsm_x4(smem_u32(&sm.ks[stage][g * 16 + lrow][kt * 16 + lcol]), r0, r1, r2, r3);
        mma_bf16(s[2 * g], aq[kt], r0, r2);
        mma_bf16(s[2 * g + 1], aq[kt], r1, r3);
      }
    }

    // Base-2 scores; the causal tile masks everything past the row position.
    #pragma unroll
    for (int nt = 0; nt < 8; ++nt) {
      s[nt][0] *= kScaleLog2e;
      s[nt][1] *= kScaleLog2e;
      s[nt][2] *= kScaleLog2e;
      s[nt][3] *= kScaleLog2e;
    }
    if (diag) {
      const int row_lo = row_group + groupID;
      #pragma unroll
      for (int nt = 0; nt < 8; ++nt) {
        const int c = sm.tile_key[ti] + nt * 8 + 2 * tig;
        s[nt][0] = (c <= row_lo) ? s[nt][0] : -INFINITY;
        s[nt][1] = (c + 1 <= row_lo) ? s[nt][1] : -INFINITY;
        s[nt][2] = (c <= row_lo + 8) ? s[nt][2] : -INFINITY;
        s[nt][3] = (c + 1 <= row_lo + 8) ? s[nt][3] : -INFINITY;
      }
    }

    // Online softmax: one row maximum and sum per warp row (4-lane reduce).
    float mx0 = -INFINITY, mx1 = -INFINITY;
    #pragma unroll
    for (int nt = 0; nt < 8; ++nt) {
      mx0 = fmaxf(mx0, fmaxf(s[nt][0], s[nt][1]));
      mx1 = fmaxf(mx1, fmaxf(s[nt][2], s[nt][3]));
    }
    mx0 = fmaxf(mx0, __shfl_xor_sync(0xffffffffu, mx0, 1));
    mx0 = fmaxf(mx0, __shfl_xor_sync(0xffffffffu, mx0, 2));
    mx1 = fmaxf(mx1, __shfl_xor_sync(0xffffffffu, mx1, 1));
    mx1 = fmaxf(mx1, __shfl_xor_sync(0xffffffffu, mx1, 2));

    const float m0 = fmaxf(rowmax[0], mx0);
    const float m1 = fmaxf(rowmax[1], mx1);
    const float alpha0 = ex2(rowmax[0] - m0);
    const float alpha1 = ex2(rowmax[1] - m1);
    rowmax[0] = m0;
    rowmax[1] = m1;

    #pragma unroll
    for (int nt = 0; nt < 16; ++nt) {
      acc[nt][0] *= alpha0;
      acc[nt][1] *= alpha0;
      acc[nt][2] *= alpha1;
      acc[nt][3] *= alpha1;
    }

    float sum0 = 0.f, sum1 = 0.f;
    #pragma unroll
    for (int nt = 0; nt < 8; ++nt) {
      s[nt][0] = ex2(s[nt][0] - m0);
      s[nt][1] = ex2(s[nt][1] - m0);
      s[nt][2] = ex2(s[nt][2] - m1);
      s[nt][3] = ex2(s[nt][3] - m1);
      sum0 += s[nt][0] + s[nt][1];
