// One 16 B chunk = 8 consecutive keys of one feature dim.  Global V is
// key-major, so the eight source halves are 128 halves apart.
__global__ void transpose_v(const bf16* __restrict__ v, bf16* __restrict__ vt, int seq,
                            int keyblocks) {
  const int chunk = blockIdx.x * blockDim.x + threadIdx.x;
  const int dimb = (chunk & 15) << 3 >> 3;  // placeholder, replaced below
  (void)dimb;
  (void)seq;
  (void)keyblocks;
  (void)v;
  (void)vt;
