    if (ti + 1 < ntiles) cp_wait<1>(); else cp_wait<0>();
    __syncthreads();
    afence();
    if (ti + kStages - 1 < ntiles) prefetch(ti + kStages - 1, (ti + kStages - 1) % kStages);

