      p[ks][1] = pack_bf16(s[8 * ks + 2], s[8 * ks + 3]);
      p[ks][2] = pack_bf16(s[8 * ks + 4], s[8 * ks + 5]);
      p[ks][3] = pack_bf16(s[8 * ks + 6], s[8 * ks + 7]);
    }

    // O += P V over the same 64 keys, 128 feature columns: 4 k-steps of m64n128k16.
    wfence();
    #pragma unroll
    for (int ks = 0; ks < 4; ++ks) {
      const uint64_t dv = gdesc(vtile + ks * kVStepAdv, kDescLbo, kDescSbo);
