    }
    wcommit();
    wwait<0>();
  }

  // Normalize and store: rows row_lo and row_lo+8 of this thread.
  const float i0 = rsum[0] > 0.f ? 1.f / rsum[0] : 0.f;
  const float i1 = rsum[1] > 0.f ? 1.f / rsum[1] : 0.f;
  bf16* orow =
      out + (((size_t)b * kHeads + hq) * seq + (size_t)qb * kRows + row_lo) * kDim + 2 * tig;
  #pragma unroll
  for (int cg = 0; cg < 16; ++cg) {
