__global__ void transpose_v(const bf16* __restrict__ v, bf16* __restrict__ vt,
                            int64_t chunks, int seq, int keyblocks) {
  const int64_t chunk = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
