  uint64_t d = 0;
  d |= (uint64_t)(((uint64_t)__cvta_generic_to_shared(p) >> 4) & 0x3FFF);
  d |= ((uint64_t)(lbo >> 4) & 0x3FFF) << 16;
  d |= ((uint64_t)(sbo >> 4) & 0x3FFF) << 32;
