  cudaMallocManaged(&k, kRows * kDim * sizeof(bf16));
  cudaMallocManaged(&d, 64 * 64 * sizeof(float));
  srand(3);
  for (int i = 0; i < 64 * kDim; ++i) q[i] = __float2bfloat16((float)(rand() % 2001 - 1000) / 512.f);
  for (int i = 0; i < kRows * kDim; ++i) k[i] = __float2bfloat16((float)(rand() % 2001 - 1000) / 512.f);
  std::vector<double> ref(64 * 64);
  for (int r = 0; r < 64; ++r) for (int c = 0; c < 64; ++c) {
    double s = 0;
    for (int x = 0; x < kDim; ++x)
      s += (double)__bfloat162float(q[r * kDim + x]) * (double)__bfloat162float(k[c * kDim + x]);
    ref[r * 64 + c] = s;
  }
  for (int amap = 0; amap < 2; ++amap) {
    for (int i = 0; i < 64 * 64; ++i) d[i] = -1e30f;
    qk<<<1, 128>>>(q, k, amap, 1, d);
    if (cudaDeviceSynchronize() != cudaSuccess) { printf("err\n"); return 1; }
    double worst = 0; int wr = 0, wc = 0; double scale = 0;
    for (int r = 0; r < 64; ++r) for (int c = 0; c < 64; ++c) {
      scale = std::max(scale, fabs(ref[r * 64 + c]));
      double e = fabs(ref[r * 64 + c] - (double)d[r * 64 + c]);
      if (e > worst) { worst = e; wr = r; wc = c; }
    }
