// ---- device code (shared by standalone test and bundle) ----
using bf16 = __nv_bfloat16;

constexpr int kHeads = 32;
constexpr int kKVHeads = 8;
constexpr int kDim = 128;
constexpr int kCapacity = 16;

constexpr int kRows = 128;              // query rows per CTA == problem block size
constexpr int kKeys = 64;               // keys per pipeline stage
constexpr int kTilesPerBlock = kRows / kKeys;
constexpr int kMaxTiles = kCapacity * kTilesPerBlock;
constexpr int kThreads = 256;           // two 128-thread warpgroups
constexpr int kStages = 3;
constexpr int kTileElems = kKeys * kDim;
constexpr int kChunks = kTileElems / 8; // 16 B cp.async chunks per tile
constexpr int kVKeysPerBlock = 8;       // keys per transposed core-matrix block
constexpr int kVBlockElems = kDim * kVKeysPerBlock;  // halves per transposed key block
constexpr float kScaleLog2e = 1.4426950408889634f / 11.313708498984761f;

// WGMMA reads its B operand as core matrices of 8 rows x 16 B, and the 16 B
// always span the contraction axis.  K contracts over the feature dim, V over
// the key index, so V is staged transposed:
//
//   K (k = dim):  il (key,dim) = (key>>3)*1024 + (dim>>3)*64 + (key&7)*8 + (dim&7)
//   V (k = key):  ilt(key,dim) = (key>>3)*1024 + (dim>>3)*64 + (dim&7)*8 + (key&7)
//
// Both use LBO = 2048 B (key-block stride) and SBO = 128 B (dim-block stride).
// A 64-key stage advances the K base by 128 halves and the V base by 2048 halves.
constexpr uint32_t kDescLbo = 2048;
constexpr uint32_t kDescSbo = 128;
constexpr int kKStepAdv = 128;
constexpr int kVStepAdv = 2048;

__device__ __forceinline__ constexpr int il(int key, int dim) {
  return ((key >> 3) * 16 + (dim >> 3)) * 64 + (key & 7) * 8 + (dim & 7);
}
__device__ __forceinline__ constexpr int ilt(int key, int dim) {
  return ((key >> 3) * 16 + (dim >> 3)) * 64 + (dim & 7) * 8 + (key & 7);
}

struct alignas(16) Shared {
  bf16 ks[kStages][kTileElems];
  bf16 vs[kStages][kTileElems];
  int ntiles;
  int tile_ksrc[kMaxTiles];  // element offset of the key tile inside a K plane
  int tile_vsrc[kMaxTiles];  // half offset of the key tile inside a transposed plane
  int tile_key[kMaxTiles];   // tile offset inside its block (causal mask coordinate)
  int tile_diag[kMaxTiles];  // 1 when the causal mask applies
};

__device__ __forceinline__ uint32_t smem_u32(const void* p) {
  return static_cast<uint32_t>(__cvta_generic_to_shared(p));
}
__device__ __forceinline__ uint64_t gdesc(const void* p, uint32_t lbo, uint32_t sbo) {
  uint64_t d = (uint64_t)(((uint64_t)smem_u32(p) >> 4) & 0x3FFF);
  d |= ((uint64_t)(lbo >> 4) & 0x3FFF) << 16;
  d |= ((uint64_t)(sbo >> 4) & 0x3FFF) << 32;
  return d;
}

