// vmode 0: V[k][n]=k ; 1: V[k][n]=n ; 2: V[k][n]=(k==5&&n==100)?1:0
__global__ void pv(const bf16* vg, int lbo, int sbo, int vmode, float* out) {
  __shared__ __align__(1024) bf16 tile[kK * kN];
  for (int i = threadIdx.x; i < kK * kN; i += blockDim.x) {
    const int key = i / kN, dim = i % kN;
    tile[ilT(key, dim)] = vg[i];
  }
  __syncthreads();
  asm volatile(\"fence.proxy.async.shared::cta;\" ::: \"memory\");
  const int tid = threadIdx.x, lane = tid & 31, warp = tid >> 5;
  const int gid = lane >> 2, tig = lane & 3;
  const int r0 = warp * 16 + gid, r1 = r0 + 8;
  uint32_t a[4][4];
  for (int ks = 0; ks < 4; ++ks) {
    const int klo = ks * 16 + 2 * tig, khi = klo + 8;
    a[ks][0] = (r0 == klo ? 0x3F80u : 0u) | (r0 == klo + 1 ? 0x3F800000u : 0u);
    a[ks][1] = (r1 == klo ? 0x3F80u : 0u) | (r1 == klo + 1 ? 0x3F800000u : 0u);
    a[ks][2] = (r0 == khi ? 0x3F80u : 0u) | (r0 == khi + 1 ? 0x3F800000u : 0u);
    a[ks][3] = (r1 == khi ? 0x3F80u : 0u) | (r1 == khi + 1 ? 0x3F800000u : 0u);
  }
  float d[64];
  for (int i = 0; i < 64; ++i) d[i] = 0.f;
  wfence();
