    const uint64_t desc = make_desc(&tile[ks * 2048], lbo, sbo);
    WGMMA128(d, a[ks], desc, 1);
  }
  wcommit(); wwait0();
  for (int cg = 0; cg < 16; ++cg)
    for (int rr = 0; rr < 2; ++rr)
      for (int cc = 0; cc < 2; ++cc)
        out[(size_t)(r0 + 8 * rr) * kN + 8 * cg + 2 * tig + cc] = d[4 * cg + 2 * rr + cc];
