        \"+f\"(D[52]), \"+f\"(D[53]), \"+f\"(D[54]), \"+f\"(D[55]), \"+f\"(D[56]),          \\
        \"+f\"(D[57]), \"+f\"(D[58]), \"+f\"(D[59]), \"+f\"(D[60]), \"+f\"(D[61]),          \\
